class Checker
  PROPERTIES = %w[ELECTION_SAFETY LEADER_COMPLETENESS LOG_MATCHING STATE_MACHINE_SAFETY COMMITTED_KEPT].freeze
  attr_reader :violations, :committed, :applied

  def initialize
    @violations = Hash.new(0)
    @leaders, @committed, @applied = {}, {}, {}
    @elected = @log_checks = @pair_checks = @applies = @truncations = @removed = 0
  end

  def leader(node)
    @elected += 1
    if @leaders.key?(node.term)
      @violations['ELECTION_SAFETY'] += 1 if @leaders[node.term] != node.number
    else
      @leaders[node.term] = node.number
    end
    if @committed.any? { |index, (term, _)| index > node.last_index || node.term_at(index) != term }
      @violations['LEADER_COMPLETENESS'] += 1
    end
  end

  def commit(index, term, time)
    @committed[index] ||= [term, time]
  end

  def apply(index, entry, result)
    @applies += 1
    if @applied.key?(index)
      @violations['STATE_MACHINE_SAFETY'] += 1 if @applied[index][0] != entry
    else
      @applied[index] = [entry, result]
    end
  end

  def truncate(first, entries)
    @truncations += 1
    @removed += entries.length
    entries.each_with_index do |entry, offset|
      record = @committed[first + offset]
      @violations['COMMITTED_KEPT'] += 1 if record && record[0] == entry.term
    end
  end

  def check_logs(nodes)
    @log_checks += 1
    nodes.combination(2) do |first, second|
      @pair_checks += 1
      limit = [first.last_index, second.last_index].min
      greatest = limit.downto(1).find { |index| first.term_at(index) == second.term_at(index) } || 0
      if (0...greatest).any? { |index| first.log[index] != second.log[index] }
        @violations['LOG_MATCHING'] += 1
      end
    end
  end

  def lines(maximum_term)
    details = ["terms #{maximum_term} leaders #{@leaders.length} elected #{@elected}",
               "checks #{@elected} committed #{@committed.length}",
               "checks #{@log_checks} pairs #{@pair_checks}",
               "applies #{@applies} indices #{@applied.length}",
               "truncations #{@truncations} removed #{@removed}"]
    PROPERTIES.each_with_index.map do |name, index|
      count = @violations[name]
      "#{name} #{count.zero? ? 'OK' : 'FAIL'} violations #{count} #{details[index]}"
    end
  end
end

class Minstd
  attr_reader :draws

  def initialize(seed)
    @state = seed
    @draws = 0
  end

  def draw
    @draws += 1
    @state = 48_271 * @state % 2_147_483_647
  end

  def between(low, high)
    low + draw % (high - low + 1)
  end
end

require 'set'

Entry = Data.define(:term, :command, :request)

class RaftNode
  attr_reader :number, :stats, :log
  attr_accessor :term, :voted_for, :up, :role, :commit, :applied, :store,
                :known_leader, :votes, :election_deadline, :election_record,
                :next_index, :match, :heartbeat_deadline, :quorum_deadline,
                :heard, :transfer_target, :transfer_sent, :transfer_deadline

  def initialize(number)
    @number = number
    @term = 0
    @voted_for = nil
    @log = []
    @up = true
    @stats = Hash.new(0)
    reset_volatile
  end

  def reset_volatile
    @role = 'FOLLOWER'
    @commit = @applied = 0
    @store = {}
    @known_leader = @election_deadline = @election_record = nil
    @votes = Set.new
    @next_index = {}
    @match = {}
    @heartbeat_deadline = @quorum_deadline = nil
    @heard = Set.new
    cancel_transfer
  end

  def cancel_transfer
    @transfer_target = @transfer_deadline = nil
    @transfer_sent = false
  end

  def crash
    @up = false
    reset_volatile
  end

  def last_index = @log.length
  def last_term = @log.empty? ? 0 : @log.last.term
  def term_at(index) = index.zero? ? 0 : @log[index - 1].term

  def accepts_log(index, term)
    term > last_term || (term == last_term && index >= last_index)
  end

  def self.apply_command(store, command)
    operation, key, value = command
    case operation
    when 'NOOP' then nil
    when 'SET'
      store[key] = value
      'ok'
    when 'ADD'
      store[key] = store.fetch(key, 0) + value
    when 'DEL'
      return 'missing' unless store.key?(key)
      store.delete(key)
      'deleted'
    when 'GET' then store.fetch(key, 'missing')
    end
  end
end
